    infoDiv.style.display = isVisible ? 'none' : 'block';
    arrow.style.transform = isVisible ? 'rotate(0deg)' : 'rotate(180deg)';
    button.querySelector('span').textContent = isVisible ? 'Show Citation Info' : 'Hide Citation Info';
