  buildTagCloud('#irw-hero-people-traits', CONFIG.peopleTraits);
  buildTagCloud('#irw-hero-response-attributes', CONFIG.responseAttributes);

  // Item-type card content.
  const cardDefs = [
    { id:'#irw-hero-card-choice', badgeKey:'choice', dot:'var(--purple)', label:'Choose an answer',
      body:`&lt;div class="mini-single" data-single-group&gt;&lt;div class="radio active"&gt;A&lt;/div&gt;&lt;div class="radio"&gt;B&lt;/div&gt;&lt;div class="radio"&gt;C&lt;/div&gt;&lt;div class="radio"&gt;D&lt;/div&gt;&lt;/div&gt;` },
    { id:'#irw-hero-card-likert', badgeKey:'likert', dot:'var(--pink)',   label:'Strongly agree?',
      body:`&lt;div class="mini-likert" data-likert-group&gt;&lt;span class="likert-edge"&gt;DIS&lt;/span&gt;&lt;div class="likert-dot"&gt;&lt;/div&gt;&lt;div class="likert-dot"&gt;&lt;/div&gt;&lt;div class="likert-dot"&gt;&lt;/div&gt;&lt;div class="likert-dot"&gt;&lt;/div&gt;&lt;div class="likert-dot"&gt;&lt;/div&gt;&lt;span class="likert-edge"&gt;AGR&lt;/span&gt;&lt;/div&gt;` },
    { id:'#irw-hero-card-slider', badgeKey:'slider', dot:'var(--orange)', label:'How confident?',
      body:`&lt;div class="mini-slider"&gt;&lt;div class="slider-track"&gt;&lt;div class="slider-knob"&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class="slider-nums"&gt;&lt;span&gt;0&lt;/span&gt;&lt;span&gt;100&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;` }
  ];
  cardDefs.forEach(def =&gt; {
    const el = $(def.id);
    const badge = CONFIG.badges[def.badgeKey];
    el.innerHTML = `${badge ? `&lt;div class="badge"&gt;${badge}&lt;/div&gt;` : ''}
      &lt;div class="card-label"&gt;&lt;span class="dot" style="background:${def.dot};"&gt;&lt;/span&gt;${def.label}&lt;/div&gt;
      ${def.body}`;
  });

  // Mini-demo animations (slider knob is pure CSS animation, see @keyframes
  // irwHeroSlideKnob above).
  root.querySelectorAll('[data-single-group]').forEach(group =&gt; {
    const radios = group.querySelectorAll('.radio');
    let idx = 0;
    const render = () =&gt; radios.forEach((r, i) =&gt; r.classList.toggle('active', i === idx));
    render();
    track(setInterval(() =&gt; { idx = (idx + 1) % radios.length; render(); }, 900));
  });

  root.querySelectorAll('[data-likert-group]').forEach(group =&gt; {
    const dots = group.querySelectorAll('.likert-dot');
    let idx = 0, dir = 1;
    const render = () =&gt; dots.forEach((d, i) =&gt; d.classList.toggle('active', i === idx));
    render();
    track(setInterval(() =&gt; {
      idx += dir;
      if (idx === dots.length - 1 || idx === 0) dir *= -1;
      render();
    }, 480));
  });

  // Dashed connector lines: each ring card -&gt; center of ITEMS stamp.
  // Scoped to the ITEMS box only; only meaningful once the &gt;=960px ring
  // layout is active; recomputed on resize (debounced) and via
  // ResizeObserver so it stays correct across the 760px/960px breakpoints.
  const svg = $('#irw-hero-connectors');
  const inner = $('#irw-hero-items-inner');
  const stampItems = $('#irw-hero-stamp-items');
  const cardIds = ['#irw-hero-card-choice', '#irw-hero-card-likert', '#irw-hero-card-slider'];

  const drawConnectors = () =&gt; {
    if (window.innerWidth &lt; 960) { svg.innerHTML = ''; return; }
    const innerRect = inner.getBoundingClientRect();
    if (innerRect.width === 0) return;
    const items = stampItems.getBoundingClientRect();
    const itemsCenter = {
      x: items.left + items.width / 2 - innerRect.left,
      y: items.top + items.height / 2 - innerRect.top
    };
    let html = '';
    cardIds.forEach(id =&gt; {
      const r = $(id).getBoundingClientRect();
      const cx = r.left + r.width / 2 - innerRect.left;
      const cy = r.bottom - innerRect.top;
      html += `&lt;line x1="${cx}" y1="${cy}" x2="${itemsCenter.x}" y2="${itemsCenter.y}"
                stroke="#1c1c22" stroke-width="2" stroke-dasharray="6 6" stroke-opacity="0.35" /&gt;`;
    });
    svg.innerHTML = html;
  };

  requestAnimationFrame(() =&gt; requestAnimationFrame(drawConnectors));
  let resizeTimer;
  const onResize = () =&gt; { clearTimeout(resizeTimer); resizeTimer = setTimeout(drawConnectors, 120); };
  window.addEventListener('resize', onResize);
  const resizeObserver = new ResizeObserver(() =&gt; drawConnectors());
  resizeObserver.observe(inner);

  invalidation.then(() =&gt; {
    intervals.forEach(id =&gt; clearInterval(id));
    clearTimeout(resizeTimer);
    window.removeEventListener('resize', onResize);
    resizeObserver.disconnect();
  });

  return root;
}
